export interface ActionRecord {
  id: string;
  action_name: string;
  action_desc?: string | null;
  group?: string | null;
}

export class ValidationError extends Error {
  public invalidActionIds: string[];
  constructor(message: string, invalidActionIds: string[] = []) {
    super(message);
    this.name = 'ValidationError';
    this.invalidActionIds = invalidActionIds;
  }
}

export async function GetActions(): Promise<ActionRecord[]> {
  // Actions are global (not scoped per restaurant). Return id, name, desc and group.
  const rows = await runQuery<{
    id: string;
    action_name: string;
    action_desc: string | null;
    group: string | null;
  }>(
    `
      select id, action_name, action_desc, "group"
      from "Actions"
      order by coalesce("group", 'Test'), action_name
    `,
    [],
  );

  return rows.map((r) => ({ id: r.id, action_name: r.action_name, action_desc: r.action_desc ?? null, group: r.group ?? null }));
}

export async function CreateRole(
  restaurantId: string,
  role_name: string,
  actions_performable: string[] = [],
): Promise<RoleRecord> {
  const context = await requireRestaurantContext(restaurantId);
  const name = role_name.trim().toLowerCase();
  if (!name) {
    throw new Error("Role name is required");
  }

  const existing = await runQuery<{ id: string; role_name: string; actions_performable: unknown }>(
    `
      select id, role_name, actions_performable
      from "Roles"
      where res_id = $1 and lower(role_name) = lower($2)
      limit 1
    `,
    [context.res_id, name],
  );

  const normalizedActions = Array.from(
    new Set(actions_performable.map((entry) => String(entry).trim()).filter(Boolean)),
  );
  // Validate that provided action IDs exist in the Actions table.
  if (normalizedActions.length > 0) {
    const found = await runQuery<{ id: string }>(
      `
        select id
        from "Actions"
        where id::text = any($1::text[])
      `,
      [normalizedActions],
    );
    const foundIds = new Set(found.map((r) => r.id));
    const invalid = normalizedActions.filter((id) => !foundIds.has(id));
    if (invalid.length > 0) {
      throw new ValidationError(`Invalid action ids: ${invalid.join(",")}`, invalid);
    }
  }

  const row = existing[0];
  if (row) {
    await runQuery(
      `
        update "Roles"
        set actions_performable = $3::json
        where id = $1 and res_id = $2
      `,
      [row.id, context.res_id, JSON.stringify(normalizedActions)],
    );

    return {
      id: row.id,
      role_name: row.role_name,
      actions_performable: normalizedActions,
    };
  }

  const id = randomUUID();
  await runQuery(
    `
      insert into "Roles" (id, created_at, role_name, actions_performable, res_id)
      values ($1, now(), $2, $3::json, $4)
    `,
    [id, name, JSON.stringify(normalizedActions), context.res_id],
  );

  return {
    id,
    role_name: name,
    actions_performable: normalizedActions,
  };
}

async function getEmployeeRoleRow(
  context: RestaurantContext,
  employeeId: string,
  client?: PoolClient,
): Promise<{ emp_id: string; emp_roles: unknown } | null> {
  const rows = await runQuery<{ emp_id: string; emp_roles: unknown }>(
    `
      select l.emp_id, e.emp_roles
      from "Login" l
      join "Employees" e
        on e.id = l.emp_id and e.res_id = l.res_id and e.outlet_id = l.outlet_id
      where
        l.res_id = $1
        and l.outlet_id = $2
        and l.emp_id = $3
      limit 1
    `,
    [context.res_id, context.outlet_id, employeeId.trim()],
    client,
  );

  return rows[0] ?? null;
}

export async function AssignRoleToEmployee(
  restaurantId: string,
  employeeId: string,
  roleName: string,
): Promise<void> {
  const context = await requireRestaurantContext(restaurantId);
  const raw = String(roleName ?? "").trim();
  if (!raw) {
    throw new Error("Role is required");
  }

  await withTransaction(async (client) => {
    // If the incoming value is a UUID, treat it as a custom role id.
    let entryToAdd: string;
    if (isUuid(raw)) {
      const roleRows = await runQuery<{ id: string; role_name: string }>(
        `select id, role_name from "Roles" where id = $1 and res_id = $2 limit 1`,
        [raw, context.res_id],
        client,
      );
      if (!roleRows[0]) {throw new Error("Role does not exist");}
      entryToAdd = roleRows[0].id; // store id for custom role
    } else {
      const normalizedRole = raw.toLowerCase();
      if (["admin", "employee", "valet", "waiter", "cashier", "captain", "manager"].includes(normalizedRole)) {
        entryToAdd = normalizedRole; // core role name
      } else {
        // lookup custom role by name and store its id
        const roleRows = await runQuery<{ id: string }>(
          `select id from "Roles" where res_id = $1 and lower(role_name) = lower($2) limit 1`,
          [context.res_id, normalizedRole],
          client,
        );
        if (!roleRows[0]) {
          throw new Error("Role does not exist");
        }
        entryToAdd = roleRows[0].id;
      }
    }

    const employee = await getEmployeeRoleRow(context, employeeId, client);
    if (!employee) {
      throw new Error("Employee not found");
    }

    const roles = parseEmployeeRoles(employee.emp_roles);
    const nextAll = Array.from(new Set([...roles.all, entryToAdd]));
    const nextPrimary = roles.primary || "employee";

    await runQuery(
      `
        update "Employees"
        set emp_roles = $4::json
        where id = $1 and res_id = $2 and outlet_id = $3
      `,
      [
        employee.emp_id,
        context.res_id,
        context.outlet_id,
        JSON.stringify({ primary: nextPrimary, all: nextAll }),
      ],
      client,
    );
  });
}

export async function RemoveRoleFromEmployee(
  restaurantId: string,
  employeeId: string,
  roleName: string,
): Promise<void> {
  const context = await requireRestaurantContext(restaurantId);
  const raw = String(roleName ?? "").trim();
  if (!raw) {throw new Error("Role is required");}

  await withTransaction(async (client) => {
    const employee = await getEmployeeRoleRow(context, employeeId, client);
    if (!employee) {
      throw new Error("Employee not found");
    }

    const roles = parseEmployeeRoles(employee.emp_roles);
    let nextAll: string[];
    if (isUuid(raw)) {
      // remove by id
      nextAll = roles.all.filter((entry) => entry !== raw);
    } else {
      const normalizedRole = raw.toLowerCase();
      if (["admin", "employee", "valet", "waiter"].includes(normalizedRole)) {
        nextAll = roles.all.filter((entry) => entry !== normalizedRole);
      } else {
        // custom role name: try to resolve to id and remove id; also remove legacy name if present
        const roleRows = await runQuery<{ id: string }>(
          `select id from "Roles" where res_id = $1 and lower(role_name) = lower($2) limit 1`,
          [context.res_id, normalizedRole],
          client,
        );
        const roleId = roleRows[0]?.id ?? null;
        nextAll = roles.all.filter((entry) => entry !== normalizedRole && entry !== roleId);
      }
    }

    const nextPrimary = roles.primary === raw || roles.primary === raw.toLowerCase()
      ? (nextAll.find((r) => ["admin", "employee", "valet", "waiter"].includes(r)) ?? "employee")
      : roles.primary;

    const normalizedAll = Array.from(new Set([nextPrimary, ...nextAll]));

    await runQuery(
      `
        update "Employees"
        set emp_roles = $4::json
        where id = $1 and res_id = $2 and outlet_id = $3
      `,
      [
        employee.emp_id,
        context.res_id,
        context.outlet_id,
        JSON.stringify({ primary: nextPrimary, all: normalizedAll }),
      ],
      client,
    );
  });
}

export async function DeleteRole(
  restaurantId: string,
  roleId: string,
): Promise<boolean> {
  const context = await requireRestaurantContext(restaurantId);
  if (!isUuid(roleId)) {
    return false;
  }

  return withTransaction(async (client) => {
    const roleRows = await runQuery<{ id: string; role_name: string }>(
      `
        select id, role_name
        from "Roles"
        where id = $1 and res_id = $2
        limit 1
      `,
      [roleId, context.res_id],
      client,
    );
    const role = roleRows[0];
    if (!role) {return false;}
    if (["admin", "employee", "valet"].includes(role.role_name.trim().toLowerCase())) {
      throw new Error("Core roles cannot be deleted");
    }

    await runQuery(
      `
        delete from "Roles"
        where id = $1 and res_id = $2
      `,
      [role.id, context.res_id],
      client,
    );

    const employees = await runQuery<{ id: string; emp_roles: unknown }>(
      `
        select id, emp_roles
        from "Employees"
        where res_id = $1 and outlet_id = $2
      `,
      [context.res_id, context.outlet_id],
      client,
    );

    for (const employee of employees) {
      const parsed = parseEmployeeRoles(employee.emp_roles);
      // Employee entries might contain role ids (custom roles) or role names (core roles or legacy). Remove both where applicable.
      if (!parsed.all.includes(role.id) && !parsed.all.includes(role.role_name)) {
        continue;
      }

      const all = parsed.all.filter((entry) => entry !== role.role_name && entry !== role.id);
      const primary = parsed.primary === role.role_name || parsed.primary === role.id
        ? (all.find((entry) => ["admin", "employee", "valet", "waiter"].includes(entry)) ?? "employee")
        : parsed.primary;
      const normalizedAll = Array.from(new Set([primary, ...all]));

      await runQuery(
        `
          update "Employees"
          set emp_roles = $4::json
          where id = $1 and res_id = $2 and outlet_id = $3
        `,
        [
          employee.id,
          context.res_id,
          context.outlet_id,
          JSON.stringify({ primary, all: normalizedAll }),
        ],
        client,
      );
    }

    return true;
  });
}

export async function GetRestaurantUserRole(
  restaurantId: string,
  employeeId: string,
): Promise<RestaurantUser["role"] | null> {
  const context = await requireRestaurantContext(restaurantId);
  const normalizedEmployeeId = employeeId.trim();
  if (!normalizedEmployeeId) {return null;}

  // Accept either employee username (case-insensitive) or employee UUID (emp_id)
  const normalizedEmployeeLower = normalizedEmployeeId.toLowerCase();

  const rows = await runQuery<{ role_primary: string | null }>(
    `
      select e.emp_roles->>'primary' as role_primary
      from "Login" l
      join "Employees" e
        on e.id = l.emp_id and e.res_id = l.res_id and e.outlet_id = l.outlet_id
      where
        l.res_id = $1
        and l.outlet_id = $2
        and (
          lower(l.emp_username) = $3
          or l.emp_id = $4
        )
      limit 1
    `,
    [context.res_id, context.outlet_id, normalizedEmployeeLower, normalizedEmployeeId],
  );

  const row = rows[0];
  return row ? toRole(row.role_primary) : null;
}

// Same memo-bypass hazard as ensureOutletColumns had (a passed client skipped
// the boolean), fixed the same way. No current caller passes a client, but the
// signature invites one, and this DDL block ALTERs a column TYPE — far too heavy
// to ever re-run inside a request. ensureLazyTable memoizes it unconditionally.
async function ensureFeedbackColumns(client?: PoolClient): Promise<void> {
  await ensureLazyTable("Feedback_entries.feedback_cols", () => ensureFeedbackColumnsDdl(client));
}

async function ensureFeedbackColumnsDdl(client?: PoolClient): Promise<void> {
  // Service-recovery: low-rating feedback becomes an internal ticket staff resolve.
  await runQuery(`alter table "Feedback_entries" add column if not exists recovery_status text`, [], client);
  await runQuery(`alter table "Feedback_entries" add column if not exists recovery_resolved_at timestamptz`, [], client);
  await runQuery(`alter table "Feedback_entries" add column if not exists recovery_resolved_by text`, [], client);
  await runQuery(`alter table "Feedback_entries" add column if not exists recovery_note text`, [], client);
  // NPS: optional 0–10 recommend score asked on the feedback form.
  await runQuery(`alter table "Feedback_entries" add column if not exists nps integer`, [], client);
  // overall_rating was an INTEGER, so an average of 4.8 was stored as 5 — the
  // guest saw 4.8 on their phone and the dashboard showed 5/5. Widen it to two
  // decimals so the stored score is the score that was actually given.
  await runQuery(
    `do $$
     begin
       if exists (
         select 1 from information_schema.columns
         where table_schema = 'public' and table_name = 'Feedback_entries'
           and column_name = 'overall_rating' and data_type = 'integer'
       ) then
         alter table "Feedback_entries" alter column overall_rating type numeric(3,2);
       end if;
     end $$;`,
    [],
    client,
  );
}

export async function AddFeedbackEntry(
  restaurantId: string,
  employeeId: string,
  entry: FeedbackSubmissionInput,
): Promise<{ id: string; submitted_at: Date; recovery: boolean; overall_rating: number; waiter_name: string | null }> {
  const context = await requireRestaurantContext(restaurantId);
  await ensureFeedbackColumns();
  const submittedAt = new Date();

  const ratings = entry.category_ratings
    .filter((r) => r.key?.trim() && r.label?.trim())
    .map((r) => ({
      key: r.key.trim(),
      label: r.label.trim(),
      rating: clampRating(r.rating),
      question: r.question?.trim() || null,
      follow_up: r.follow_up?.trim() || null,
      follow_up_answer: r.follow_up_answer?.trim() || null,
    }));

  if (ratings.length === 0) {
    throw new Error("At least one category rating is required");
  }

  // Keep the true average (2dp) — Math.round() here turned a genuine 4.8 into a
  // 5/5 on the dashboard while the guest's own screen said 4.8.
  const overallRating = Math.max(
    1,
    Math.min(5, round2(ratings.reduce((acc, cur) => acc + cur.rating, 0) / ratings.length)),
  );

  // Low-rating feedback opens a service-recovery ticket for staff to follow up.
  const needsRecovery = overallRating <= 3 || ratings.some((r) => r.rating <= 2);

  // Attribute to the waiter when one was resolved from the link; otherwise store
  // NULL (unattributed feedback still saves — see migration 013).
  const empUuid = employeeId && isUuid(employeeId) ? employeeId : null;

  const id = randomUUID();
  const visitDate =
    entry.visit_date instanceof Date && !Number.isNaN(entry.visit_date.getTime())
      ? entry.visit_date
      : submittedAt;

  // Optional 0–10 NPS answer; anything non-numeric stores NULL (question skipped).
  const nps =
    typeof entry.nps === "number" && Number.isFinite(entry.nps)
      ? Math.max(0, Math.min(10, Math.round(entry.nps)))
      : null;

  await runQuery(
    `
      insert into "Feedback_entries"
        (id, submitted_at, res_id, outlet_id, emp_id, cust_name, comments, overall_rating, cattegory_ratings, visit_date, source, recovery_status, nps)
      values
        ($1, $2, $3, $4, $5, $6, $7, $8, $9::json, $10, $11, $12, $13)
    `,
    [
      id,
      submittedAt,
      context.res_id,
      context.outlet_id,
      empUuid,
      entry.customer_name?.trim() || null,
      entry.comments?.trim() || null,
      overallRating,
      JSON.stringify(ratings),
      visitDate,
      entry.source?.trim() || "feedback_form",
      needsRecovery ? "open" : null,
      nps,
    ],
  );

  // Resolve the waiter's display name (best-effort) so callers can attribute
  // low-score alerts without another round trip.
  let waiterName: string | null = null;
  if (empUuid) {
    try {
      const empRows = await runQuery<{ name: string | null }>(
        `select trim(concat("emp_Fname", ' ', coalesce("emp_Lname", ''))) as name
           from "Employees" where id = $1 and res_id = $2 limit 1`,
        [empUuid, context.res_id],
      );
      waiterName = empRows[0]?.name?.trim() || null;
    } catch {
      waiterName = null;
    }
  }

  return { id, submitted_at: submittedAt, recovery: needsRecovery, overall_rating: overallRating, waiter_name: waiterName };
}

export async function GetFeedbackEntries(
  restaurantId: string,
  limit = 100,
): Promise<any[]> {
  const context = await requireRestaurantContext(restaurantId);
  const safeLimit = Math.max(1, Math.min(limit, 5000));

  const rows = await runQuery<{
    id: string;
    res_id: string;
    emp_id: string;
    cust_name: string | null;
    comments: string | null;
    overall_rating: number;
    category_ratings: unknown;
    visit_date: Date;
    source: string;
    nps: number | string | null;
    submitted_at: Date;
  }>(
    `
      select
        id,
        res_id,
        emp_id,
        cust_name,
        comments,
        overall_rating,
        cattegory_ratings as category_ratings,
        visit_date,
        source,
        nps,
        submitted_at
      from "Feedback_entries"
      where res_id = $1 and outlet_id = $2
      order by submitted_at desc
      limit $3
    `,
    [context.res_id, context.outlet_id, safeLimit],
  );

  return rows.map((row) => ({
    id: row.id,
    restaurant_id: context.inputId,
    employee_id: row.emp_id,
    customer_name: row.cust_name,
    visit_date: row.visit_date ? new Date(row.visit_date) : null,
    comments: row.comments,
    overall_rating: parseNumeric(row.overall_rating),
    category_ratings: Array.isArray(row.category_ratings)
      ? (row.category_ratings as FeedbackCategoryRatingInput[])
      : [],
    image_theme: null,
    source: row.source,
    // Surfaced so the dashboard's expanded view can show the recommend score
    // alongside the per-question ratings.
    nps: row.nps == null ? null : Number(row.nps),
    submitted_at: new Date(row.submitted_at),
  }));
}

export async function GetFeedbackSummary(
  restaurantId: string,
): Promise<FeedbackSummary> {
  const rows = await GetFeedbackEntries(restaurantId, 5000);
  const now = new Date();
  const last30Start = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);

  let overallTotal = 0;
  let overallCount = 0;
  let last30DaysResponses = 0;
  const categoryTotals = new Map<string, { label: string; total: number; count: number }>();

  for (const row of rows) {
    if (typeof row.overall_rating === "number") {
      overallTotal += row.overall_rating;
      overallCount += 1;
    }

    if (row.submitted_at >= last30Start) {
      last30DaysResponses += 1;
    }

    for (const category of row.category_ratings ?? []) {
      const key = category.key.trim();
      if (!key) {continue;}
      const existing = categoryTotals.get(key) ?? {
        label: category.label,
        total: 0,
        count: 0,
      };
      existing.total += clampRating(category.rating);
      existing.count += 1;
      if (category.label.trim().length > 0) {
        existing.label = category.label;
      }
      categoryTotals.set(key, existing);
    }
  }

  const categoryAverages: Record<string, { label: string; average: number | null }> = {};
  for (const [key, value] of categoryTotals.entries()) {
    categoryAverages[key] = {
      label: value.label,
      average: value.count > 0 ? Number((value.total / value.count).toFixed(2)) : null,
    };
  }

  return {
    totalResponses: rows.length,
    averageRating: overallCount > 0 ? Number((overallTotal / overallCount).toFixed(2)) : null,
    categoryAverages,
    last30DaysResponses,
  };
}

export interface RecoveryTicket {
  id: string;
  customer_name: string | null;
  overall_rating: number;
  comments: string | null;
  category_ratings: { key: string; label: string; rating: number; follow_up_answer: string | null }[];
  submitted_at: string;
  recovery_status: string;
  recovery_resolved_at: string | null;
  recovery_resolved_by: string | null;
  recovery_note: string | null;
}

// Service-recovery tickets: low-rating feedback that needs staff follow-up. By
// default returns OPEN tickets only.
export async function GetRecoveryTickets(restaurantId: string, includeResolved = false): Promise<RecoveryTicket[]> {
  const context = await requireRestaurantContext(restaurantId);
  await ensureFeedbackColumns();
  const rows = await runQuery<{
    id: string;
    cust_name: string | null;
    comments: string | null;
    overall_rating: number | string | null;
    category_ratings: unknown;
    submitted_at: Date;
    recovery_status: string | null;
    recovery_resolved_at: Date | null;
    recovery_resolved_by: string | null;
    recovery_note: string | null;
  }>(
    `select id, cust_name, comments, overall_rating, cattegory_ratings as category_ratings, submitted_at,
            recovery_status, recovery_resolved_at, recovery_resolved_by, recovery_note
       from "Feedback_entries"
       where res_id = $1 and outlet_id = $2
         and recovery_status is not null
         ${includeResolved ? "" : "and recovery_status = 'open'"}
       order by submitted_at desc
       limit 300`,
    [context.res_id, context.outlet_id],
  );
  return rows.map((r) => {
    const cats = Array.isArray(r.category_ratings) ? (r.category_ratings) : [];
    return {
      id: r.id,
      customer_name: r.cust_name,
      overall_rating: parseNumeric(r.overall_rating),
      comments: r.comments,
      // Surface the low-rated categories + the reason the guest gave.
      category_ratings: cats
        .map((c) => ({
          key: String(c?.key ?? ""),
          label: String(c?.label ?? ""),
          rating: parseNumeric(c?.rating),
          follow_up_answer: typeof c?.follow_up_answer === "string" ? c.follow_up_answer : null,
        }))
        .filter((c) => c.rating > 0 && c.rating <= 3),
      submitted_at: new Date(r.submitted_at).toISOString(),
      recovery_status: r.recovery_status ?? "open",
      recovery_resolved_at: r.recovery_resolved_at ? new Date(r.recovery_resolved_at).toISOString() : null,
      recovery_resolved_by: r.recovery_resolved_by,
      recovery_note: r.recovery_note,
    };
  });
}

export async function ResolveRecoveryTicket(
  restaurantId: string,
  id: string,
  note?: string,
  byUsername?: string,
): Promise<{ success: true }> {
  const context = await requireRestaurantContext(restaurantId);
  await ensureFeedbackColumns();
  await runQuery(
    `update "Feedback_entries"
       set recovery_status = 'resolved', recovery_resolved_at = now(), recovery_resolved_by = $4, recovery_note = $5
       where id = $1 and res_id = $2 and outlet_id = $3 and recovery_status is not null`,
    [id, context.res_id, context.outlet_id, byUsername ?? null, note?.trim() || null],
  );
  return { success: true };
}

// --- Attendance / working hours ---------------------------------------------
async function ensureAttendanceTable(_client?: PoolClient): Promise<void> {
  await ensureLazyTable("Attendance", async () => {
    await runQuery(
      `create table if not exists "Attendance" (
         id uuid primary key,
         res_id uuid not null,
         outlet_id uuid,
         emp_id uuid not null,
         clock_in timestamptz not null default now(),
         clock_out timestamptz,
         created_at timestamptz not null default now()
       )`,
    );
    // Approval workflow: new clock-ins are 'pending' until an admin approves.
    // status NULL = legacy rows from before the workflow — treated as approved.
    // clock_in is ALWAYS the moment the employee clocked in; approval only
    // stamps approved_at/approved_by and never rewrites the shift times.
    await runQuery(`alter table "Attendance" add column if not exists status text`);
    await runQuery(`alter table "Attendance" add column if not exists approved_by text`);
    await runQuery(`alter table "Attendance" add column if not exists approved_at timestamptz`);
    // Dedicated audit action so approvals show up with an honest name in the log.
    await runQuery(
      `insert into "Actions" (id, action_name, action_desc, "group")
       values ('e7a41c3b-5a20-4f6e-9d38-6c2b9a51f0aa', 'Approve Attendance', 'Review (approve/reject) employee clock-ins', 'Restaurant Specific'::"Action_groups"),
              ('b3f8d6a1-2c47-4e0b-8f5d-9e6a7c8b0d21', 'Attendance Clock Event', 'Employee clocked in or out', 'Restaurant Specific'::"Action_groups")
       on conflict (id) do nothing`,
    ).catch(() => {/* seeded by migrations under least-privilege runtimes */});
    await applyTenantRls("Attendance");
  });
}

// status filter for anything that COUNTS attendance time: legacy NULL or approved.
const ATTENDANCE_COUNTED = `(status is null or status = 'approved')`;

async function findOpenShift(context: RestaurantContext, employeeId: string): Promise<{ id: string; clock_in: Date } | null> {
  const rows = await runQuery<{ id: string; clock_in: Date }>(
    `select id, clock_in from "Attendance"
       where res_id = $1 and outlet_id = $2 and emp_id = $3 and clock_out is null
       order by clock_in desc limit 1`,
    [context.res_id, context.outlet_id, employeeId],
  );
  return rows[0] ?? null;
}

export async function ClockIn(restaurantId: string, employeeId: string): Promise<{ clocked_in: true; since: string }> {
  const context = await requireRestaurantContext(restaurantId);
  await ensureAttendanceTable();
  if (!isUuid(employeeId)) {throw new Error("Invalid employee");}
  const open = await findOpenShift(context, employeeId);
  if (open) {return { clocked_in: true, since: new Date(open.clock_in).toISOString() };}
  // clock_in defaults to now() — the REAL clock-in moment; approval never moves it.
  const rows = await runQuery<{ clock_in: Date }>(
    `insert into "Attendance" (id, res_id, outlet_id, emp_id, status) values ($1, $2, $3, $4, 'pending') returning clock_in`,
    [randomUUID(), context.res_id, context.outlet_id, employeeId],
  );
  return { clocked_in: true, since: new Date(rows[0]?.clock_in ?? new Date()).toISOString() };
}

// Admin approves (or rejects) a pending clock-in. Approval stamps who/when but
// leaves clock_in exactly as recorded at the moment the employee clocked in.
export async function SetAttendanceApproval(
  restaurantId: string,
  attendanceId: string,
  approve: boolean,
  approvedBy?: string,
): Promise<{ id: string; emp_id: string; status: string; clock_in: string }> {
  const context = await requireRestaurantContext(restaurantId);
  await ensureAttendanceTable();
  const rows = await runQuery<{ id: string; emp_id: string; status: string; clock_in: Date }>(
    `update "Attendance"
        set status = $4, approved_by = $5, approved_at = now()
      where id = $1 and res_id = $2 and outlet_id = $3 and status = 'pending'
      returning id, emp_id, status, clock_in`,
    [attendanceId, context.res_id, context.outlet_id, approve ? "approved" : "rejected", approvedBy || null],
  );
  if (!rows[0]) {throw new Error("Clock-in not found or already reviewed");}
  return { ...rows[0], clock_in: new Date(rows[0].clock_in).toISOString() };
}

export async function ClockOut(restaurantId: string, employeeId: string): Promise<{ clocked_in: false; minutes: number }> {
  const context = await requireRestaurantContext(restaurantId);
  await ensureAttendanceTable();
  const open = await findOpenShift(context, employeeId);
  if (!open) {throw new Error("You are not clocked in");}
  const rows = await runQuery<{ clock_in: Date; clock_out: Date }>(
    `update "Attendance" set clock_out = now() where id = $1 and res_id = $2 and outlet_id = $3 returning clock_in, clock_out`,
    [open.id, context.res_id, context.outlet_id],
  );
  const r = rows[0];
  const minutes = r ? Math.max(0, Math.round((new Date(r.clock_out).getTime() - new Date(r.clock_in).getTime()) / 60000)) : 0;
  return { clocked_in: false, minutes };
}

export async function GetMyAttendance(restaurantId: string, employeeId: string): Promise<{ clocked_in: boolean; since: string | null; today_minutes: number; pending_approval: boolean }> {
  const context = await requireRestaurantContext(restaurantId);
  await ensureAttendanceTable();
  if (!isUuid(employeeId)) {return { clocked_in: false, since: null, today_minutes: 0, pending_approval: false };}
  const open = await findOpenShift(context, employeeId);
  const now = new Date();
  const startOfDay = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate())).toISOString();
  const rows = await runQuery<{ clock_in: Date; clock_out: Date | null; status: string | null }>(
    `select clock_in, clock_out, status from "Attendance"
       where res_id = $1 and outlet_id = $2 and emp_id = $3 and clock_in >= $4`,
    [context.res_id, context.outlet_id, employeeId, startOfDay],
  );
  let today = 0;
  let pendingApproval = false;
  for (const r of rows) {
    if (r.status === "rejected") {continue;} // rejected shifts never count
    if (r.status === "pending") {pendingApproval = true;}
    const end = r.clock_out ? new Date(r.clock_out).getTime() : Date.now();
    today += Math.max(0, (end - new Date(r.clock_in).getTime()) / 60000);
  }
  return { clocked_in: !!open, since: open ? new Date(open.clock_in).toISOString() : null, today_minutes: Math.round(today), pending_approval: pendingApproval };
}

export interface AttendanceSummaryRow { emp_id: string; name: string; minutes: number; shifts: number; open: boolean }
export interface PendingClockIn { id: string; emp_id: string; name: string; clock_in: string; clock_out: string | null }
export async function GetAttendanceSummary(
  restaurantId: string,
  fromIso?: string,
  toIso?: string,
): Promise<{ from: string; to: string; rows: AttendanceSummaryRow[]; pending: PendingClockIn[] }> {
  const context = await requireRestaurantContext(restaurantId);
  await ensureAttendanceTable();
  const range = normalizeReportRange(fromIso, toIso, context.timezone);
  const rows = await runQuery<{ id: string; emp_id: string; clock_in: Date; clock_out: Date | null; status: string | null; fname: string | null; lname: string | null }>(
    `select a.id, a.emp_id, a.clock_in, a.clock_out, a.status, e."emp_Fname" as fname, e."emp_Lname" as lname
       from "Attendance" a
       left join "Employees" e on e.id = a.emp_id and e.res_id = a.res_id
       where a.res_id = $1 and a.outlet_id = $2 and a.clock_in >= $3 and a.clock_in < $4
       order by a.clock_in desc`,
    [context.res_id, context.outlet_id, range.fromIso, range.toIso],
  );
  const byEmp = new Map<string, AttendanceSummaryRow>();
  const pending: PendingClockIn[] = [];
  for (const r of rows) {
    const name = [r.fname, r.lname].filter(Boolean).join(" ").trim() || "Employee";
    if (r.status === "pending") {
      pending.push({ id: r.id, emp_id: r.emp_id, name, clock_in: new Date(r.clock_in).toISOString(), clock_out: r.clock_out ? new Date(r.clock_out).toISOString() : null });
    }
    // Rejected shifts never count; pending shifts count only once approved.
    if (r.status === "pending" || r.status === "rejected") {continue;}
    const end = r.clock_out ? new Date(r.clock_out).getTime() : Date.now();
    const mins = Math.max(0, Math.round((end - new Date(r.clock_in).getTime()) / 60000));
    const e = byEmp.get(r.emp_id) ?? { emp_id: r.emp_id, name, minutes: 0, shifts: 0, open: false };
    e.minutes += mins;
    e.shifts += 1;
    if (!r.clock_out) {e.open = true;}
    e.name = name;
    byEmp.set(r.emp_id, e);
  }
  return { from: range.fromDate, to: range.toDate, rows: [...byEmp.values()].sort((a, b) => b.minutes - a.minutes), pending };
}

// --- Employee leave ----------------------------------------------------------
// "Attendance" records what a person DID; this records what they were EXCUSED
// from. Without it getStaffAttendanceStats counts an approved holiday as an
// absence, which is the one number an owner uses to judge reliability.
//
// Dates here are the RESTAURANT's calendar days, stored as bare `date` and
// always computed from the tenant zone in TypeScript (dayKeyOf / addDaysToKey).
// Nothing on this path may use Postgres `current_date`: the DB session runs in
// UTC, so through the tenant's own late shift it names the wrong day.

export type LeaveType = "sick" | "casual" | "unpaid" | "holiday";
export type LeaveStatus = "requested" | "approved" | "rejected";

// Mirrors the CHECK constraints in migration 024. Plain string unions rather
// than a Postgres enum, matching how every other workflow state in this schema
// is stored ("Attendance".status, "DiscountRequests".status, "PurchaseOrders"
// .status are all text) — the only real enums here are catalogues, not row state.
const LEAVE_TYPES: readonly LeaveType[] = ["sick", "casual", "unpaid", "holiday"];
/** Upper bound on a single leave request — see CreateLeaveRequest for why. */
const LEAVE_MAX_DAYS = 366;
const LEAVE_STATUSES: readonly LeaveStatus[] = ["requested", "approved", "rejected"];

export function normalizeLeaveType(raw: unknown): LeaveType | null {
  const v = (typeof raw === "string" ? raw : "").trim().toLowerCase();
  return (LEAVE_TYPES as readonly string[]).includes(v) ? (v as LeaveType) : null;
}
export function normalizeLeaveStatus(raw: unknown): LeaveStatus | null {
  const v = (typeof raw === "string" ? raw : "").trim().toLowerCase();
  return (LEAVE_STATUSES as readonly string[]).includes(v) ? (v as LeaveStatus) : null;
}

const DAY_KEY_RE = /^\d{4}-\d{2}-\d{2}$/;

export interface LeaveRecord {
  id: string;
  emp_id: string;
  employee_name: string;
  leave_type: LeaveType;
  /** Inclusive restaurant calendar days, "YYYY-MM-DD". */
  start_day: string;
  end_day: string;
  /** Inclusive day count — a single-day leave is 1, never 0. */
  days: number;
  status: LeaveStatus;
  reason: string | null;
  /** Employee id of the actor, NOT a username — see the note on the columns in
   *  migration 024. The resolved display names ride alongside so the app never
   *  has to render a raw uuid or make a second lookup to say who signed it off. */
  requested_by: string | null;
  requested_by_name: string | null;
  decided_by: string | null;
  decided_by_name: string | null;
  decided_at: string | null;
  created_at: string;
}

interface LeaveRow {
  id: string;
  emp_id: string;
  fname: string | null;
  lname: string | null;
  leave_type: string;
  start_day: Date | string;
  end_day: Date | string;
  status: string;
  reason: string | null;
  requested_by: string | null;
  decided_by: string | null;
  req_fname?: string | null;
  req_lname?: string | null;
  dec_fname?: string | null;
  dec_lname?: string | null;
  decided_at: Date | string | null;
  created_at: Date | string;
}

// Every read below selects the two `date` columns through to_char(), so a day key
// arrives as text and this is a passthrough. That is deliberate: node-postgres
// parses a bare `date` into a JS Date at LOCAL midnight, not UTC midnight, so on
// any host east of Greenwich toISOString().slice(0,10) returns the PREVIOUS day —
// a leave filed for the 3rd came back as the 2nd. When a Date does reach here,
// read its LOCAL components, which is the value pg actually decoded.
const dayKeyFromDb = (v: Date | string): string => {
  if (!(v instanceof Date)) { return v.slice(0, 10); }
  const p = (n: number): string => String(n).padStart(2, "0");
  return `${String(v.getFullYear())}-${p(v.getMonth() + 1)}-${p(v.getDate())}`;
};

// `date` -> 'YYYY-MM-DD' in SQL, so no zone is ever applied on the way out.
const DAY_COLS = `to_char(l.start_day, 'YYYY-MM-DD') as start_day,
            to_char(l.end_day, 'YYYY-MM-DD') as end_day`;

const personName = (f?: string | null, l?: string | null): string | null =>
  [f, l].filter(Boolean).join(" ").trim() || null;

// requested_by / decided_by hold an employee id in a text column, so the join is
// written uuid::text = text. Casting the OTHER way ($col::uuid) would throw on
// any row a future writer fills with a username instead of an id, taking the
// whole list down; this way such a row simply resolves to no name.
const LEAVE_ACTOR_JOINS = `
       left join "Employees" rq on rq.res_id = l.res_id and rq.id::text = l.requested_by
       left join "Employees" dc on dc.res_id = l.res_id and dc.id::text = l.decided_by`;
const LEAVE_ACTOR_COLS = `rq."emp_Fname" as req_fname, rq."emp_Lname" as req_lname,
            dc."emp_Fname" as dec_fname, dc."emp_Lname" as dec_lname`;

const LEAVE_SELECT_ONE = `select l.id, l.emp_id, e."emp_Fname" as fname, e."emp_Lname" as lname,
            l.leave_type, ${DAY_COLS}, l.status, l.reason,
            l.requested_by, l.decided_by, l.decided_at, l.created_at,
            ${LEAVE_ACTOR_COLS}
       from "EmployeeLeaves" l
       left join "Employees" e on e.id = l.emp_id and e.res_id = l.res_id and e.outlet_id = l.outlet_id${LEAVE_ACTOR_JOINS}
      where l.id = $1 and l.res_id = $2 and l.outlet_id = $3`;

/** Whole days from `from` to `to` INCLUSIVE. Both are zone-free day keys, so this
 *  is plain UTC arithmetic and never lands on a DST half-day. */
function inclusiveDayCount(fromKey: string, toKey: string): number {
  const a = Date.parse(`${fromKey}T00:00:00Z`);
  const b = Date.parse(`${toKey}T00:00:00Z`);
  if (!Number.isFinite(a) || !Number.isFinite(b) || b < a) { return 0; }
  return Math.round((b - a) / 86_400_000) + 1;
}

function mapLeaveRow(r: LeaveRow): LeaveRecord {
  const start_day = dayKeyFromDb(r.start_day);
  const end_day = dayKeyFromDb(r.end_day);
  return {
    id: r.id,
    emp_id: r.emp_id,
    employee_name: [r.fname, r.lname].filter(Boolean).join(" ").trim() || "Employee",
    leave_type: normalizeLeaveType(r.leave_type) ?? "casual",
    start_day,
    end_day,
    days: inclusiveDayCount(start_day, end_day),
    status: normalizeLeaveStatus(r.status) ?? "requested",
    reason: r.reason,
    requested_by: r.requested_by,
    requested_by_name: personName(r.req_fname, r.req_lname),
    decided_by: r.decided_by,
    decided_by_name: personName(r.dec_fname, r.dec_lname),
    decided_at: iso(r.decided_at),
    created_at: iso(r.created_at) ?? "",
  };
}

/** Single leave, outlet-scoped, with both actor names resolved. */
async function readLeaveById(
  context: RestaurantContext,
  leaveId: string,
): Promise<LeaveRecord | null> {
  const rows = await runQuery<LeaveRow>(LEAVE_SELECT_ONE, [leaveId, context.res_id, context.outlet_id]);
  return rows[0] ? mapLeaveRow(rows[0]) : null;
}

async function ensureEmployeeLeavesTable(): Promise<void> {
  await ensureLazyTable("EmployeeLeaves", async () => {
    // Mirrors migration 024 so whichever runs first wins and the other is a
    // no-op. The composite FK is the only shape Postgres accepts: "Employees" is
    // keyed on (id, res_id, outlet_id), not on id alone.
    await runQuery(
      `create table if not exists "EmployeeLeaves" (
         id uuid primary key default gen_random_uuid(),
         created_at timestamptz not null default now(),
         res_id uuid not null,
         outlet_id uuid not null,
         emp_id uuid not null,
         leave_type text not null default 'casual'
           check (leave_type in ('sick','casual','unpaid','holiday')),
         start_day date not null,
         end_day date not null,
         status text not null default 'requested'
           check (status in ('requested','approved','rejected')),
         reason text,
         requested_by text,
         decided_by text,
         decided_at timestamptz,
         constraint employee_leaves_range_ordered check (end_day >= start_day)
       )`,
    );
    await runQuery(
      `create index if not exists employee_leaves_emp_day_idx
         on "EmployeeLeaves" (res_id, outlet_id, emp_id, start_day, end_day)`,
    );
    await runQuery(
      `create index if not exists employee_leaves_status_day_idx
         on "EmployeeLeaves" (res_id, outlet_id, status, start_day, end_day)`,
    );
    await applyTenantRls("EmployeeLeaves");
  });
}

/** The employee must belong to THIS tenant and THIS outlet — the composite FK in
 *  migration 024 enforces it, but resolving first turns a would-be 500 into an
 *  honest 400 and gives the audit line a real name. */
async function resolveLeaveEmployee(
  context: RestaurantContext,
  employeeId: string,
): Promise<{ id: string; name: string } | null> {
  if (!isUuid(employeeId)) { return null; }
  const rows = await runQuery<{ id: string; fname: string | null; lname: string | null }>(
    `select id, "emp_Fname" as fname, "emp_Lname" as lname
       from "Employees" where id = $1 and res_id = $2 and outlet_id = $3 limit 1`,
    [employeeId, context.res_id, context.outlet_id],
  );
  if (rows.length === 0) { return null; }
  const r = rows[0];
  return { id: r.id, name: [r.fname, r.lname].filter(Boolean).join(" ").trim() || "Employee" };
}

export interface LeaveFilter {
  emp_id?: string;
  /** Restaurant day keys. A leave is included when its range OVERLAPS [from,to];
   *  filtering on start_day alone would hide a leave already in progress. */
  from?: string;
  to?: string;
  status?: LeaveStatus;
  limit?: number;
  offset?: number;
}

export async function ListEmployeeLeaves(
  restaurantId: string,
  opts: LeaveFilter = {},
): Promise<{ leaves: LeaveRecord[]; total: number; has_more: boolean; from: string; to: string }> {
  const context = await requireRestaurantContext(restaurantId);
  await ensureEmployeeLeavesTable();
  const tz = context.timezone;
  const safeLimit = Math.max(1, Math.min(opts.limit ?? 100, 500));
  const safeOffset = Math.max(0, Math.round(opts.offset ?? 0));

  // Default window: the 30 restaurant-days ending today, plus the next 90 — a
  // leave list is as much about what is COMING as about what happened.
  const todayKey = dayKeyOf(new Date(), tz);
  const fromOpt = opts.from ?? "", toOpt = opts.to ?? "";
  const from = DAY_KEY_RE.test(fromOpt) ? fromOpt : addDaysToKey(todayKey, -29);
  const to = DAY_KEY_RE.test(toOpt) ? toOpt : addDaysToKey(todayKey, 90);

  const og = isAllOutlets() ? "true" : "false";
  const where: string[] = [
    "l.res_id = $1",
    `(${og} or l.outlet_id = $2)`,
    "l.start_day <= $4::date",
    "l.end_day >= $3::date",
  ];
  const params: unknown[] = [context.res_id, context.outlet_id, from, to];
  if (opts.emp_id) { params.push(opts.emp_id); where.push(`l.emp_id = $${String(params.length)}::uuid`); }
  if (opts.status) { params.push(opts.status); where.push(`l.status = $${String(params.length)}`); }
  const whereSql = where.join(" and ");

  const countRows = await runQuery<{ total: string }>(
    `select count(*)::text as total from "EmployeeLeaves" l where ${whereSql}`,
    params,
  );
  const total = Math.max(0, Math.round(Number(countRows[0]?.total ?? 0)));

  params.push(safeLimit); const limIdx = `$${String(params.length)}`;
  params.push(safeOffset); const offIdx = `$${String(params.length)}`;
  const rows = await runQuery<LeaveRow>(
    `select l.id, l.emp_id, e."emp_Fname" as fname, e."emp_Lname" as lname,
            l.leave_type, ${DAY_COLS}, l.status, l.reason,
            l.requested_by, l.decided_by, l.decided_at, l.created_at,
            ${LEAVE_ACTOR_COLS}
       from "EmployeeLeaves" l
       left join "Employees" e on e.id = l.emp_id and e.res_id = l.res_id and e.outlet_id = l.outlet_id${LEAVE_ACTOR_JOINS}
      where ${whereSql}
      -- Latest-starting first, then a stable id tiebreak: start_day alone is not
      -- unique, and without the tiebreak paging duplicates and skips rows.
      order by l.start_day desc, l.id desc
      limit ${limIdx} offset ${offIdx}`,
    params,
  );

  return {
    leaves: rows.map(mapLeaveRow),
    total,
    has_more: safeOffset + rows.length < total,
    from,
    to,
  };
}

export async function CreateLeaveRequest(
  restaurantId: string,
  input: { emp_id: string; leave_type?: string; start_day?: string; end_day?: string; reason?: string; requested_by?: string },
): Promise<LeaveRecord> {
  const context = await requireRestaurantContext(restaurantId);
  await ensureEmployeeLeavesTable();
  const tz = context.timezone;

  const employee = await resolveLeaveEmployee(context, input.emp_id.trim());
  if (!employee) { throw new Error("Unknown employee for this outlet"); }

  const leaveType = normalizeLeaveType(input.leave_type ?? "casual");
  if (!leaveType) { throw new Error(`leave_type must be one of ${LEAVE_TYPES.join(", ")}`); }

  // The restaurant's today, never the server's and never Postgres's.
  const todayKey = dayKeyOf(new Date(), tz);
  const startOpt = input.start_day ?? "", endOpt = input.end_day ?? "";
  const startDay = DAY_KEY_RE.test(startOpt) ? startOpt : todayKey;
  const endDay = DAY_KEY_RE.test(endOpt) ? endOpt : startDay;
  const requestedDays = inclusiveDayCount(startDay, endDay);
  if (requestedDays <= 0) { throw new Error("end_day must be on or after start_day"); }
  // A typo in the year ("2926") was accepted as a 328,719-day leave. Approving
  // one would mark the employee on leave effectively forever, and attendance
  // reads that as excused absence — so the damage outlives the typo. A year is
  // far past any real request and still leaves room for extended unpaid leave.
  if (requestedDays > LEAVE_MAX_DAYS) {
    throw new Error(`A leave request cannot span more than ${String(LEAVE_MAX_DAYS)} days (asked for ${String(requestedDays)})`);
  }

  // A day already covered by a live (requested or approved) leave must not be
  // claimed twice: two overlapping approvals would each excuse the same absence,
  // and the leave-day count the attendance stats subtract would be wrong.
  const clash = await runQuery<{ id: string; start_day: Date | string; end_day: Date | string; status: string }>(
    `select id, to_char(start_day, 'YYYY-MM-DD') as start_day,
            to_char(end_day, 'YYYY-MM-DD') as end_day, status from "EmployeeLeaves"
      where res_id = $1 and outlet_id = $2 and emp_id = $3
        and status <> 'rejected'
        and start_day <= $5::date and end_day >= $4::date
      order by start_day asc limit 1`,
    [context.res_id, context.outlet_id, employee.id, startDay, endDay],
  );
  if (clash[0]) {
    const c = clash[0];
    throw new Error(
      `${employee.name} already has a ${c.status} leave covering ${dayKeyFromDb(c.start_day)} to ${dayKeyFromDb(c.end_day)}`,
    );
  }

  const rows = await runQuery<{ id: string }>(
    `insert into "EmployeeLeaves" (res_id, outlet_id, emp_id, leave_type, start_day, end_day, status, reason, requested_by)
     values ($1, $2, $3, $4, $5::date, $6::date, 'requested', $7, $8)
     returning id`,
    [
      context.res_id, context.outlet_id, employee.id, leaveType, startDay, endDay,
      (input.reason ?? "").trim() || null,
      (input.requested_by ?? "").trim() || null,
    ],
  );
  const newId = rows[0]?.id;
  if (!newId) { throw new Error("Failed to create leave request"); }
  // Re-read through the same joined select the other two paths use, so a created
  // leave comes back in exactly the shape a listed one does — the requester's
  // name included, rather than the caller having to look it up.
  const created = await readLeaveById(context, newId);
  if (!created) { throw new Error("Failed to create leave request"); }
  return created;
}

/**
 * Approve or reject one leave.
 *
 * IDEMPOTENT: deciding a leave that already carries the target status is a
 * no-op — the original decided_by / decided_at are preserved and `changed` comes
 * back false. A double-tap (or a retried request) must not rewrite who signed it
 * off or when. Flipping a decision the other way IS allowed and does re-stamp,
 * because that is a genuine second decision by a real person.
 */
export async function DecideLeaveRequest(
  restaurantId: string,
  leaveId: string,
  approve: boolean,
  decidedBy?: string,
): Promise<{ leave: LeaveRecord; changed: boolean }> {
  const context = await requireRestaurantContext(restaurantId);
  await ensureEmployeeLeavesTable();
  const target: LeaveStatus = approve ? "approved" : "rejected";
  if (!isUuid(leaveId)) { throw new Error("Unknown leave request"); }

  const existing = await readLeaveById(context, leaveId);
  if (!existing) { throw new Error("Unknown leave request"); }
  if (existing.status === target) { return { leave: existing, changed: false }; }

  // `status <> $4` makes the no-op case a property of the WRITE, not of the read
  // above it. Two approvals racing each other would both pass an in-TypeScript
  // check and the loser would silently re-stamp decided_by/decided_at with the
  // second person's name; here exactly one row is updated and the loser reports
  // changed:false, so the log keeps whoever actually made the decision.
  const updated = await runQuery<{ id: string }>(
    `update "EmployeeLeaves"
        set status = $4, decided_by = $5, decided_at = now()
      where id = $1 and res_id = $2 and outlet_id = $3 and status <> $4
      returning id`,
    [leaveId, context.res_id, context.outlet_id, target, (decidedBy ?? "").trim() || null],
  );
  const after = await readLeaveById(context, leaveId);
  if (!after) { throw new Error("Unknown leave request"); }
  return { leave: after, changed: updated.length > 0 };
}

/**
 * Approved leave days per employee over [fromKey, toKey], as restaurant day keys.
 *
 * generate_series over two bare `date` columns — no zone conversion anywhere, so
 * these keys are directly comparable with the ones getStaffAttendanceStats
 * derives from clock_in `at time zone $tz`.
 */
async function approvedLeaveDaysByEmployee(
  resId: string,
  outletId: string,
  outletGuard: string,
  fromKey: string,
  toKey: string,
): Promise<Map<string, Set<string>>> {
  await ensureEmployeeLeavesTable();
  const rows = await runQuery<{ emp_id: string; day: string }>(
    `select l.emp_id, to_char(d, 'YYYY-MM-DD') as day
       from "EmployeeLeaves" l
       cross join lateral generate_series(
         greatest(l.start_day, $3::date),
         least(l.end_day, $4::date),
         interval '1 day'
       ) d
      where l.res_id = $1 and (${outletGuard} or l.outlet_id = $2)
        and l.status = 'approved'
        and l.start_day <= $4::date and l.end_day >= $3::date`,
    [resId, outletId, fromKey, toKey],
    // Deliberately NOT wrapped in a catch. ensureEmployeeLeavesTable() above
    // creates the table when it is missing, so the only way this can throw is a
    // real schema fault — and swallowing that would silently report every
    // approved holiday as an absence, which is the exact bug this table exists
    // to fix. A 500 is the honest outcome.
  );
  const out = new Map<string, Set<string>>();
  for (const r of rows) {
    const set = out.get(r.emp_id) ?? new Set<string>();
    set.add(r.day);
    out.set(r.emp_id, set);
  }
  return out;
}

// Restaurant-wide employee count (ALL outlets) for plan-limit enforcement.
// GetRestaurantUsers is intentionally outlet-scoped for the management UI, so do
// not reuse it for the limit check.
export async function GetRestaurantEmployeeCount(restaurantId: string): Promise<number> {
  const context = await requireRestaurantContext(restaurantId);
  const rows = await runQuery<{ n: number | string }>(
    `select count(*)::int as n from "Employees" where res_id = $1`,
    [context.res_id],
  );
  return Number(rows[0]?.n ?? 0);
}

// Pre-auth / public: list a restaurant's outlets (id + name ONLY) for the login
// outlet picker. Resolves the restaurant EXACTLY like login does (slug OR id),
// RLS-safe, mirroring resolveRestaurantContext's res_id resolution. An unknown
// restaurant returns [] (the caller surfaces {outlets:[]} with 200 so existence
// is never revealed). Never returns addresses/phones/revenue — names + ids only.
export async function GetRestaurantOutletsPublic(
  slugOrId: string,
): Promise<{ id: string; name: string }[]> {
  const raw = String(slugOrId ?? "").trim();
  if (!raw) {return [];}
  const normalized = normalizeRestaurantId(raw);
  const rows = await runQuery<{ id: string; name: string | null }>(
    `
      select o.id as id, o.outlet_name as name
      from "Restaurant" r
      join "Outlets" o on o.res_id = r.id
      where
        lower(r.res_username) = lower($1)
        or lower(r.res_username) = lower($2)
        or r.id::text = $3
      order by o.created_at asc
    `,
    [raw, normalized, raw],
  );
  return rows.map((r) => ({ id: r.id, name: r.name ?? "" }));
}

// The restaurant OWNER (superadmin) is the earliest-created admin login across
// ALL outlets of the restaurant — STABLE regardless of the active/selected
// outlet. Falls back to the earliest login overall if no admin currently holds
// the role. Takes the res_id (UUID) directly. This deliberately IGNORES the
// active outlet / all-outlets mode so the owner never changes as outlets switch.
async function resolveRestaurantOwnerId(resId: string, client?: PoolClient): Promise<string | null> {
  const adminRows = await runQuery<{ employee_id: string }>(
    `
      select e.id as employee_id
      from "Login" l
      join "Employees" e
        on e.id = l.emp_id and e.res_id = l.res_id and e.outlet_id = l.outlet_id
      where l.res_id = $1
        and (
          lower(coalesce(e.emp_roles->>'primary', '')) = 'admin'
          or e.emp_roles::text ilike '%"admin"%'
        )
      order by l.created_at asc
      limit 1
    `,
    [resId],
    client,
  );
  if (adminRows[0]?.employee_id) {return adminRows[0].employee_id;}

  const anyRows = await runQuery<{ employee_id: string }>(
    `
      select e.id as employee_id
      from "Login" l
      join "Employees" e
        on e.id = l.emp_id and e.res_id = l.res_id and e.outlet_id = l.outlet_id
      where l.res_id = $1
      order by l.created_at asc
      limit 1
    `,
    [resId],
    client,
  );
  return anyRows[0]?.employee_id ?? null;
}

export async function GetRestaurantUsers(
  restaurantId: string,
): Promise<RestaurantUser[]> {
  const context = await requireRestaurantContext(restaurantId);
  const og = isAllOutlets() ? "true" : "false";

  const rows = await runQuery<{
    employee_id: string;
    row_outlet_id: string | null;
    emp_username: string;
    fname: string;
    lname: string;
    role_primary: string | null;
    emp_roles: unknown;
  }>(
    `
      select
        e.id as employee_id,
        l.outlet_id as row_outlet_id,
        l.emp_username,
        e."emp_Fname" as fname,
        e."emp_Lname" as lname,
        e.emp_roles->>'primary' as role_primary,
        e.emp_roles as emp_roles
      from "Login" l
      join "Employees" e
        on e.id = l.emp_id and e.res_id = l.res_id and e.outlet_id = l.outlet_id
      where l.res_id = $1 and (${og} or l.outlet_id = $2)
      order by l.created_at asc
    `,
    [context.res_id, context.outlet_id],
  );

  const mapped = rows.map((row) => ({
    // include the Employees.id (UUID) as `id` and `employee_id` so callers can match by UUID
    id: row.employee_id,
    res_id: context.res_id,
    // In all-outlets mode rows span every outlet, so report each login's REAL
    // outlet (falling back to the bound outlet) instead of the default.
    outlet_id: row.row_outlet_id ?? context.outlet_id,
    employee_id: row.employee_id,
    employee_Username: row.emp_username,
    emp_Fname: String(row.fname ?? row.emp_username ?? "").trim(),
    emp_Lname: row.lname ?? null,
    password: "", // never expose the stored password hash to clients
    role: toRole(row.role_primary),
    role_all: parseEmployeeRoles(row.emp_roles).all,
    is_superadmin: false,
  }));

  // The superadmin is the restaurant OWNER — the earliest-created admin login
  // across ALL outlets (resolved once, independent of the currently-viewed
  // outlet). Flag whichever row in this outlet-scoped list is that owner. If the
  // owner isn't a user of the viewed outlet, no row is flagged here (correct —
  // they aren't in this outlet), but the owner id itself stays stable everywhere.
  const ownerId = await resolveRestaurantOwnerId(context.res_id);
  if (ownerId) {
    for (const u of mapped) {
      if (u.employee_id === ownerId) {u.is_superadmin = true;}
    }
  }

  return mapped;
}

// Every employee of the restaurant (across ALL outlets) holding any of the given
// role identifiers — a core role NAME ("manager") or a custom role UUID, since
// emp_roles.all stores custom roles by id. Used to revoke live sessions when a
// role's permission set is edited: session.actions is resolved once at login, so
// the holders must re-authenticate to pick the new permissions up.
export async function GetEmployeeIdsWithRole(
  restaurantId: string,
  roleIdentifiers: string[],
): Promise<string[]> {
  const wanted = new Set(
    (roleIdentifiers ?? [])
      .map((entry) => String(entry ?? "").trim().toLowerCase())
      .filter(Boolean),
  );
  if (wanted.size === 0) {return [];}
  const context = await requireRestaurantContext(restaurantId);
  const rows = await runQuery<{ id: string; emp_roles: unknown }>(
    `select id, emp_roles from "Employees" where res_id = $1`,
    [context.res_id],
  );
  const ids: string[] = [];
  for (const row of rows) {
    const roles = parseEmployeeRoles(row.emp_roles);
    if (roles.all.some((entry) => wanted.has(entry.toLowerCase()))) {ids.push(row.id);}
  }
  return ids;
}

// The owner employee id (superadmin) for a restaurant — the earliest-created
// admin. Used to protect the owner from removal / password reset by others.
export async function GetSuperadminEmployeeId(restaurantId: string): Promise<string | null> {
  // Resolve directly against ALL outlets so the owner is STABLE regardless of the
  // active outlet — do NOT route through the outlet-scoped GetRestaurantUsers.
  const context = await requireRestaurantContext(restaurantId);
  return resolveRestaurantOwnerId(context.res_id);
}

// Admin sets/resets a user's login password directly (rehashes + stores it).
// Also resolves any pending forgot-password requests for that user.
export async function SetUserPassword(
  restaurantId: string,
  employeeId: string,
  newPassword: string,
): Promise<boolean> {
  const pass = String(newPassword ?? "").trim();
  if (pass.length < 4) {throw new Error("Password must be at least 4 characters");}
  return withTransaction(async (client) => {
    const context = await requireRestaurantContext(restaurantId, client);
    const hash = await hashPassword(pass);
    const rows = await runQuery<{ emp_id: string }>(
      `update "Login" set emp_pass = $4
         where res_id = $1 and outlet_id = $2 and emp_id = $3
         returning emp_id`,
      [context.res_id, context.outlet_id, employeeId, hash],
      client,
    );
    if (!rows[0]) {throw new Error("User not found");}
    await ensurePasswordResetTable(client);
    await runQuery(
      `update "PasswordResetRequests" set status = 'resolved', resolved_at = now()
         where res_id = $1 and outlet_id = $2 and emp_id = $3 and status = 'pending'`,
      [context.res_id, context.outlet_id, employeeId],
      client,
    );
    return true;
  });
}

// --- Forgot-password requests -----------------------------------------------
async function ensurePasswordResetTable(_client?: PoolClient): Promise<void> {
  await ensureLazyTable("PasswordResetRequests", async () => {
    await runQuery(
      `create table if not exists "PasswordResetRequests" (
         id uuid primary key,
         res_id uuid not null,
         outlet_id uuid,
         emp_id uuid not null,
         username text not null,
         status text not null default 'pending',
         created_at timestamptz not null default now(),
         resolved_at timestamptz
       )`,
    );
    await applyTenantRls("PasswordResetRequests");
  });
}

// A staff member who can't log in requests a reset (identified by username). The
// restaurant slug resolves the tenant. Always succeeds quietly when the username
// isn't found, so this can't be used to enumerate accounts.
export async function AddPasswordResetRequest(
  restaurantSlug: string,
  username: string,
  outletId?: string,
): Promise<{ success: true }> {
  const uname = String(username ?? "").trim();
  if (!uname) {throw new Error("Username is required");}
  // Only a canonical outlet id is honoured: an unresolvable one must match no
  // "Login" row (so nothing is filed) rather than quietly falling back to the
  // restaurant's first outlet the way requireRestaurantContext does.
  const wantedOutlet = isUuid(String(outletId ?? "").trim()) ? String(outletId).trim() : null;
  const context = await requireRestaurantContext(restaurantSlug, undefined, wantedOutlet ?? undefined);
  return withTenant(
    { res_id: context.res_id, outlet_id: context.outlet_id, employeeId: "", role: "" },
    async () => {
      await ensurePasswordResetTable();
      // Employee identity is PER-OUTLET ("Login" is unique on res_id + outlet_id +
      // emp_username), so one username can name different people in different
      // outlets. The outlet is therefore taken from the matched "Login" row itself:
      // stamping the request with this (unauthenticated) request's context outlet
      // filed a branch employee's request against the main outlet's namesake, where
      // only the wrong admin ever saw it.
      const rows = await runQuery<{ emp_id: string; outlet_id: string | null }>(
        `select emp_id, outlet_id from "Login"
          where res_id = $1 and lower(emp_username) = lower($2)
            and ($3::uuid is null or outlet_id = $3::uuid)
          order by outlet_id`,
        [context.res_id, uname, wantedOutlet],
      );
      // With no outlet supplied and the username live in more than one outlet there
      // is nothing to tell the two people apart, so file for each: the request then
      // always reaches the admin who can actually fulfil it, and no other.
      for (const row of rows) {
        // Collapse duplicate pending requests for the same user.
        const existing = await runQuery<{ id: string }>(
          `select id from "PasswordResetRequests" where res_id = $1 and emp_id = $2 and status = 'pending' limit 1`,
          [context.res_id, row.emp_id],
        );
        if (!existing[0]) {
          await runQuery(
            `insert into "PasswordResetRequests" (id, res_id, outlet_id, emp_id, username)
               values ($1, $2, $3, $4, $5)`,
            [randomUUID(), context.res_id, row.outlet_id, row.emp_id, uname],
          );
        }
      }
      return { success: true };
    },
  );
}

export async function GetPasswordResetRequests(
  restaurantId: string,
): Promise<{ id: string; employee_id: string; username: string; name: string; created_at: string }[]> {
  const context = await requireRestaurantContext(restaurantId);
  await ensurePasswordResetTable();
  const rows = await runQuery<{ id: string; emp_id: string; username: string; fname: string | null; lname: string | null; created_at: Date }>(
    // Scoped to the ACTIVE outlet, matching SetUserPassword (which can only reset a
    // user of that outlet): listing another branch's requests both leaked employee
    // names and offered a dismiss the admin had no business performing.
    `select r.id, r.emp_id, r.username, e."emp_Fname" as fname, e."emp_Lname" as lname, r.created_at
       from "PasswordResetRequests" r
       left join "Employees" e on e.id = r.emp_id and e.res_id = r.res_id
      where r.res_id = $1 and r.outlet_id = $2 and r.status = 'pending'
      order by r.created_at asc`,
    [context.res_id, context.outlet_id],
  );
  return rows.map((r) => ({
    id: r.id,
    employee_id: r.emp_id,
    username: r.username,
    name: `${String(r.fname ?? "").trim()} ${String(r.lname ?? "").trim()}`.trim() || r.username,
    created_at: new Date(r.created_at).toISOString(),
  }));
}

export async function ResolvePasswordResetRequest(restaurantId: string, requestId: string): Promise<boolean> {
  const context = await requireRestaurantContext(restaurantId);
  await ensurePasswordResetTable();
  await runQuery(
    `update "PasswordResetRequests" set status = 'dismissed', resolved_at = now()
       where id = $1 and res_id = $2 and outlet_id = $3 and status = 'pending'`,
    [requestId, context.res_id, context.outlet_id],
  );
  return true;
}

export async function DeleteRestaurantUser(
  restaurantId: string,
  employeeId: string,
  outletId: string
): Promise<boolean> {
  return withTransaction(async (client) => {
    const context = await requireRestaurantContext(restaurantId, client, outletId);

    // The restaurant OWNER (superadmin) — the earliest-created admin across ALL
    // outlets — cannot be removed by anyone, from any outlet. Resolve it
    // restaurant-wide (NOT the earliest admin of the currently-viewed outlet) so
    // protection is STABLE and only ever shields the real owner.
    const ownerId = await resolveRestaurantOwnerId(context.res_id, client);
    if (ownerId && ownerId === employeeId) {
      throw new Error("The restaurant owner (superadmin) cannot be removed.");
    }

    // Every employee created via AddRestaurantUser also gets a "Login" row whose
    // emp_id FK references Employees(id). Leaving it behind both blocks the delete
    // (FK violation -> the "cannot remove employees" bug) and would let a removed
    // user keep signing in, so remove credentials first.
    await runQuery(
      `delete from "Login" where res_id = $1 and outlet_id = $2 and emp_id = $3`,
      [context.res_id, context.outlet_id, employeeId],
      client,
    );

    // Bills are financial records — keep them but drop the waiter link so the FK
    // doesn't block removal of an employee who has worked tables.
    await runQuery(
      `update "Bills" set emp_id = null where res_id = $1 and outlet_id = $2 and emp_id = $3`,
      [context.res_id, context.outlet_id, employeeId],
      client,
    );

    // Attendance rows belong to the employee; clear them out.
    await ensureAttendanceTable(client);
    await runQuery(
      `delete from "Attendance" where res_id = $1 and outlet_id = $2 and emp_id = $3`,
      [context.res_id, context.outlet_id, employeeId],
      client,
    );

    // Finally remove the employee record.
    await runQuery(
      `delete from "Employees" where res_id = $1 and outlet_id = $2 and id = $3`,
      [context.res_id, context.outlet_id, employeeId],
      client,
    );

    return true;
  });
}

export interface EmployeeLoginResult {
  employeeId: string; // uuid of Employees.id
  employeeUsername: string; // login username
  role: "admin" | "employee" | "valet" | "waiter" | "cashier" | "captain" | "manager";
  role_all: string[];
  restaurantUsername: string;
  restaurantName: string;
  res_id: string;
  outlet_id: string;
  emp_Fname: string;
  emp_Lname: string | null;
  actions_set: Set<string>;
  action_names: string[];
}

// Effective lifecycle status of a restaurant ('active' | 'suspended' |
// 'expired'), via the platform SECURITY DEFINER function. Returns 'active' when
// the platform control plane isn't deployed (function/schema missing), so this
// check is purely additive.
export async function GetRestaurantAccountStatus(resId: string): Promise<string> {
  try {
    const rows = await runQuery<{ status: string | null }>(
      `select platform.restaurant_status($1::uuid) as status`,
      [resId],
    );
    return rows[0]?.status ?? "active";
  } catch (err: any) {
    if (err?.code === "42883" || err?.code === "3F000") {
      return "active"; // undefined_function / invalid_schema_name => control plane not deployed
    }
    logger.error({ err }, "get_restaurant_account_status_failed");
    return "active";
  }
}

// How many bills a restaurant currently has OPEN — a table still trading, whose
// money has not been collected. The operator console reads this before archiving
// a tenant, because archiving revokes every login: an open bill at that moment is
// stranded, and the floor state freezes with it. Same predicate the POS uses for
// "the single open bill for this table" (:3038) — status 3 is voided, closed_at
// is stamped at settlement.
//
// Runs on the TENANT pool: platform_runtime holds no grant on "Bills" and RLS is
// fail-closed there, so the control plane cannot count these on its own
// connection. res_id-scoped with an empty outlet_id is correct here — this counts
// the whole restaurant, and RLS keys solely on app.res_id.
export async function CountOpenBillsForRestaurant(resId: string): Promise<number> {
  return withTenant({ res_id: resId, outlet_id: "", employeeId: "", role: "" }, async () => {
    const rows = await runQuery<{ n: number }>(
      `select count(*)::int as n from "Bills" where res_id = $1 and status != 3 and closed_at is null`,
      [resId],
    );
    return Number(rows[0]?.n ?? 0);
  });
}

export interface RestaurantPlan {
  features: Record<string, unknown>;
  limits: Record<string, unknown>;
}

// Effective plan features + limits for a restaurant, via the platform SECURITY
// DEFINER function. Returns empty objects when the control plane isn't deployed
// or the restaurant has no plan, so feature-gating is purely additive.
export async function GetRestaurantPlan(resId: string): Promise<RestaurantPlan> {
  try {
    const rows = await runQuery<{ features: Record<string, unknown>; limits: Record<string, unknown> }>(
      `select features, limits from platform.restaurant_plan($1::uuid)`,
      [resId],
    );
    return { features: rows[0]?.features ?? {}, limits: rows[0]?.limits ?? {} };
  } catch (err: any) {
    if (err?.code === "42883" || err?.code === "3F000") {
      return { features: {}, limits: {} };
    }
    logger.error({ err }, "get_restaurant_plan_failed");
    return { features: {}, limits: {} };
  }
}

export async function AuthenticateRestaurantEmployee(
  restaurantId: string,
  employeeUsername: string,
  password: string,
  outletId?: string,
): Promise<EmployeeLoginResult | null> {
  // Optional explicit outlet: employee identity is PER-OUTLET, so the login
  // screen lets the user pick which outlet to sign into. Thread the chosen outlet
  // through as the outletOverride so the credential query binds to it. Omitted /
  // empty → unchanged (defaults to the restaurant's first/oldest outlet).
  const chosenOutlet = typeof outletId === "string" ? outletId.trim() : "";
  const context = await requireRestaurantContext(restaurantId, undefined, chosenOutlet || undefined);
  // The login outlet picker always sends an outlet ID. If an explicit outlet was
  // requested but did NOT resolve to that exact outlet of this restaurant,
  // resolveRestaurantContext silently falls back to the default outlet — reject
  // here (clean 401 upstream, never a 500) rather than authenticating against the
  // wrong/default outlet.
  if (chosenOutlet && context.outlet_id !== chosenOutlet) {
    return null;
  }
  const normalizedEmployeeUsername = employeeUsername.trim();
  if (!normalizedEmployeeUsername) {return null;}

  // Login touches tenant tables (Login/Employees/Roles), so run the lookups
  // inside the restaurant's tenant context (RLS-safe) now that res_id is known
  // from the RLS-exempt slug resolution above.
  return withTenant(
    { res_id: context.res_id, outlet_id: context.outlet_id, employeeId: "", role: "" },
    async () => {
      const rows = await runQuery<{
        emp_id: string;
        emp_username: string;
        emp_pass: string;
        emp_fname: string | null;
        emp_lname: string | null;
        role_primary: string | null;
        emp_roles: Record<string, string[]>;
        res_id: string;
        outlet_id: string;
      }>(
        `
          select
            e.id as emp_id,
            l.emp_username,
            l.emp_pass,
            e."emp_Fname" as emp_fname,
            e."emp_Lname" as emp_lname,
            e.emp_roles->>'primary' as role_primary,
            e.emp_roles as emp_roles,
            e.res_id,
            e.outlet_id
          from "Login" l
          join "Employees" e
            on e.id = l.emp_id and e.res_id = l.res_id and e.outlet_id = l.outlet_id
          where
            l.res_id = $1
            and l.outlet_id = $2
            and lower(l.emp_username) = lower($3)
          limit 1
        `,
        [context.res_id, context.outlet_id, normalizedEmployeeUsername],
      );

      const row = rows[0];
      if (!row) {return null;}

      // Verify against the stored secret (argon2 hash, or legacy plaintext).
      const passwordOk = await verifyPassword(row.emp_pass, password);
      if (!passwordOk) {return null;}

      // Transparently upgrade a legacy plaintext credential to an argon2 hash.
      if (!isHashedPassword(row.emp_pass)) {
        const upgraded = await hashPassword(password);
        await runQuery(
          `update "Login" set emp_pass = $1 where res_id = $2 and outlet_id = $3 and lower(emp_username) = lower($4)`,
          [upgraded, context.res_id, context.outlet_id, normalizedEmployeeUsername],
        );
      }

      const coreRoleName = Object.keys(CORE_ROLES);
      const actionSet = new Set<string>();
      const promises = (row.emp_roles['all'] ?? []).map(async role => {
        if (coreRoleName.includes(role)) {
          CORE_ROLES[role as CoreRoleKey].forEach(action => actionSet.add(action));
        } else {
          const actionRows = await runQuery<{ actions_performable: string[] }>(
            `select actions_performable from "Roles" where id = $1 and res_id = $2 limit 1`,
            [role, context.res_id],
          );
          if (actionRows[0]) {
            actionRows[0].actions_performable.forEach(action => actionSet.add(action));
          }
        }
      });

      await Promise.all(promises);

      if (actionSet.size === 0) {
        // Default to employee permissions if no roles or actions found
        CORE_ROLES.employee.forEach(action => actionSet.add(action));
      }

      const actionIds = Array.from(actionSet).filter((id) => isUuid(id));
      const actionNameRows = actionIds.length > 0
        ? await runQuery<{ action_name: string }>(
          `
            select action_name
            from "Actions"
            where id = any($1::uuid[])
          `,
          [actionIds],
        )
        : [];
      const action_names = actionNameRows
        .map((nameRow) => String(nameRow.action_name ?? "").trim())
        .filter((name) => name.length > 0);

      return {
        employeeId: row.emp_id,
        employeeUsername: row.emp_username,
        role: toRole(row.role_primary),
        role_all: parseEmployeeRoles(row.emp_roles).all,
        restaurantUsername: context.restaurant_slug,
        restaurantName: context.restaurant_name,
        res_id: row.res_id,
        outlet_id: row.outlet_id,
        emp_Fname: String(row.emp_fname ?? row.emp_username ?? "").trim(),
        emp_Lname: row.emp_lname ?? null,
        actions_set: actionSet,
        action_names,
      };
    },
  );
}

export async function EnsureRestaurantSeed(seed: RestaurantSeedInput): Promise<void> {
  const restaurantSlug = seed.id?.trim() || normalizeRestaurantId(seed.name);
  const profile = seed.profile ?? {};

  await withTransaction(async (client) => {
    const restaurantRows = await runQuery<{ id: string }>(
      `
        select id
        from "Restaurant"
        where lower(res_username) = lower($1)
        limit 1
      `,
      [restaurantSlug],
      client,
    );

    let resId = restaurantRows[0]?.id;
    if (!resId) {
      resId = randomUUID();
      await runQuery(
        `
          insert into "Restaurant" (id, created_at, res_username, res_name, main_office_add)
          values ($1, now(), $2, $3, $4)
        `,
        [resId, restaurantSlug, seed.name, profile.address ?? null],
        client,
      );
    } else {
      await runQuery(
        `
          update "Restaurant"
          set res_name = $2, main_office_add = $3
          where id = $1
        `,
        [resId, seed.name, profile.address ?? null],
        client,
      );
    }

    // Bind the tenant context for the remainder of the seed so the operational
    // tables' fail-closed RLS accepts these inserts during registration.
    // Transaction-local, so it clears at COMMIT. "Restaurant"/"Outlets" are
    // metadata tables and accept the rows above even before this is set.
    await client.query("select set_config('app.res_id', $1, true)", [resId]);

    const outletRows = await runQuery<{ id: string }>(
      `
        select id
        from "Outlets"
        where res_id = $1
        order by created_at asc
        limit 1
      `,
      [resId],
      client,
    );

    let outletId = outletRows[0]?.id;
    if (!outletId) {
      outletId = randomUUID();
      await runQuery(
        `
          insert into "Outlets"
            (id, created_at, oultet_username, outlet_name, outlet_add, outlet_main_ph, outlet_working_hours, res_id)
          values
            ($1, now(), $2, $3, $4, $5, $6, $7)
        `,
        [
          outletId,
          `${restaurantSlug}-main`,
          `${seed.name} Main Outlet`,
          profile.address ?? "",
          normalizePhone(profile.phone ?? "") || null,
          profile.hours ?? null,
          resId,
        ],
        client,
      );
    } else {
      await runQuery(
        `
          update "Outlets"
          set
            outlet_name = $2,
            outlet_add = $3,
            outlet_main_ph = $4,
            outlet_working_hours = $5
          where id = $1
        `,
        [
          outletId,
          `${seed.name} Main Outlet`,
          profile.address ?? "",
          normalizePhone(profile.phone ?? "") || null,
          profile.hours ?? null,
        ],
        client,
      );
    }

    const adminUsername = seed.admin.employeeId.trim();
    const adminParts = splitName(seed.admin.name);

    const loginRows = await runQuery<{ emp_id: string }>(
      `
        select emp_id
        from "Login"
        where res_id = $1 and outlet_id = $2 and lower(emp_username) = lower($3)
        limit 1
      `,
      [resId, outletId, adminUsername],
      client,
    );

    let adminEmpId = loginRows[0]?.emp_id;
    if (!adminEmpId) {
      adminEmpId = randomUUID();
      await runQuery(
        `
          insert into "Employees"
            (id, created_at, "emp_Fname", "emp_email", "emp_ph", "emp_add", emp_roles, res_id, outlet_id, "emp_Lname")
          values
            ($1, now(), $2, $3, $4, $5, $6::json, $7, $8, $9)
        `,
        [
          adminEmpId,
          adminParts.first,
          profile.email ?? null,
          normalizePhone(profile.phone ?? "") || null,
          profile.address ?? null,
          JSON.stringify({ primary: "admin", all: ["admin"] }),
          resId,
          outletId,
          adminParts.last,
        ],
        client,
      );

      await runQuery(
        `
          insert into "Login"
            (emp_id, created_at, res_id, outlet_id, emp_username, emp_pass)
          values
            ($1, now(), $2, $3, $4, $5)
        `,
        [adminEmpId, resId, outletId, adminUsername, await hashPassword(seed.admin.password)],
        client,
      );
    } else {
      await runQuery(
        `
          update "Employees"
          set
            "emp_Fname" = $4,
            "emp_Lname" = $5,
            emp_roles = $6::json,
            "emp_email" = $7,
            "emp_ph" = $8,
            "emp_add" = $9
          where id = $1 and res_id = $2 and outlet_id = $3
        `,
        [
          adminEmpId,
          resId,
          outletId,
          adminParts.first,
          adminParts.last,
          JSON.stringify({ primary: "admin", all: ["admin"] }),
          profile.email ?? null,
          normalizePhone(profile.phone ?? "") || null,
          profile.address ?? null,
        ],
        client,
      );

      await runQuery(
        `
          update "Login"
          set emp_pass = $4
          where res_id = $1 and outlet_id = $2 and lower(emp_username) = lower($3)
        `,
        [resId, outletId, adminUsername, await hashPassword(seed.admin.password)],
        client,
      );
    }

    for (const table of seed.tables) {
      const existing = await runQuery<{ id: string }>(
        `
          select id
          from "Tables"
          where res_id = $1 and outlet_id = $2 and lower(table_name) = lower($3)
          limit 1
        `,
        [resId, outletId, table.name],
        client,
      );

      if (!existing[0]) {
        await runQuery(
          `
            insert into "Tables" (id, created_at, res_id, outlet_id, table_name, capacity)
            values ($1, now(), $2, $3, $4, $5)
          `,
          [randomUUID(), resId, outletId, table.name, Math.max(1, table.capacity)],
          client,
        );
      }
    }
  });
}

// --- Durable print jobs (migration 027) --------------------------------------
//
// Every statement that touches "PrintJobs" lives here, behind a named export,
// because runQuery is module-private. The ORCHESTRATION — the TTL policy, the
// agent-version gate, the degradation when migration 027 has not been applied —
// lives in print_jobs.ts. These functions are the SQL and nothing else, and they
// THROW; deciding what a failure means is the caller's job.
//
// THE GUARANTEE, and where each half of it actually lives:
//
//   at-least-once delivery  <- the row itself. It is written BEFORE the socket
//                              emit, so a job survives an emit that reached
//                              nobody (no `io`, empty room, replica with no
//                              Redis adapter — all three are silent no-ops).
//   at-most-once printing   <- ClaimPrintJobsForAgent's lease predicate plus
//                              AckPrintJob's compare-and-swap. Neither is an
//                              in-process flag, because neither an in-process
//                              flag nor an advisory lock survives a second
//                              replica.
//
// Nothing here reads the ambient outlet. Both the producer and the replay path
// pass an explicit outlet_id: the producer has requireAuth's resolved
// auth.outlet_id, and the replay path has the outlet the agent named and proved
// membership of. resolveRestaurantContext's default branch picks the OLDEST
// outlet when it cannot resolve one (:1639), which here would mean handing one
// branch's receipts to another branch's till.

export interface PrintJobInput {
  outlet_id: string;
  bill_id: string;
  kind: "bill" | "kot";
  /** KOT only — the kitchen station this ticket belongs to. */
  station: string | null;
  esc_base64: string;
}

export interface PrintJobRow {
  id: string;
  /** Insertion order. Only ever a tiebreaker for created_at — see migration 027. */
  seq: string;
  bill_id: string;
  kind: string;
  station: string | null;
  esc_base64: string;
  created_at: Date;
  attempts: number;
}

/**
 * Persist one print job. Returns its uuid — THE identity every other guard keys
 * on (see the migration header for why bill_id cannot be that key).
 *
 * Called before the emit, never after: the row is the durable fact and the emit
 * is the fast path. An insert that landed after a successful emit would leave a
 * window in which the till has already printed and acked a job the backend does
 * not yet have a row for, and that ack would be discarded as unknown.
 */
export async function EnqueuePrintJob(resId: string, job: PrintJobInput): Promise<string> {
  const rows = await runQuery<{ id: string }>(
    `insert into "PrintJobs" (res_id, outlet_id, bill_id, kind, station, esc_base64)
     values ($1,$2,$3,$4,$5,$6)
     returning id`,
    [resId, job.outlet_id, job.bill_id, job.kind, job.station, job.esc_base64],
  );
  const id = rows[0]?.id;
  if (!id) { throw new Error("PrintJobs insert returned no id"); }
  return id;
}

/**
 * Hand this agent the outlet's outstanding jobs, oldest first, and LEASE them.
 *
 * THE THREE PREDICATES, none of them optional:
 *
 *   status in ('pending','delivered')
 *     'acked' / 'failed' / 'expired' are terminal. Dropping this is how a bill
 *     that already printed prints again on the next reconnect — and a till
 *     reconnects on every WebSocket flap, so "again" means "repeatedly".
 *
 *   claimed_until is null or claimed_until < now()
 *     THE LEASE. Two tills sharing one outlet both sit in the same socket room
 *     and both resume on reconnect. Without this both claims match and the
 *     customer gets two receipts. With it the second till's UPDATE matches zero
 *     rows and it prints nothing — and if the first till dies mid-spool the lease
 *     lapses and the second one picks the job up, so a crash costs at most one
 *     late receipt rather than a lost one.
 *
 *   created_at > (kot cutoff | bill cutoff)
 *     TTL enforced AT READ TIME, per kind. This is what makes the reaper pure
 *     hygiene rather than a correctness dependency: a database whose sweep never
 *     ran still cannot replay a stale docket. A kitchen ticket for food ordered
 *     an hour ago is actively harmful — the kitchen cooks a dish that already
 *     went out — so it expires far sooner than a customer bill.
 *
 * `for update skip locked` keeps two replicas claiming concurrently from
 * serialising on the same rows; it is NOT the guard (the lease is), it only stops
 * one resume blocking another.
 *
 * Returned rows are sorted by created_at because RETURNING has no defined order,
 * and order matters: the N station tickets of one KOT are one logical unit, and
 * dockets must reach the kitchen oldest-first.
 */
export async function ClaimPrintJobsForAgent(
  resId: string,
  outletId: string,
  agentId: string,
  cutoffs: { kot: Date; bill: Date },
  leaseUntil: Date,
  limit: number,
): Promise<PrintJobRow[]> {
  const rows = await runQuery<PrintJobRow>(
    `with due as (
       select id
         from "PrintJobs"
        where res_id = $1
          and outlet_id = $2
          and status in ('pending','delivered')
          and (claimed_until is null or claimed_until < now())
          and created_at > (case when kind = 'kot' then $3::timestamptz else $4::timestamptz end)
        order by created_at asc, seq asc
        limit $7
        for update skip locked
     )
     update "PrintJobs" p
        set status = 'delivered',
            attempts = p.attempts + 1,
            claimed_by = $5,
            claimed_until = $6::timestamptz,
            delivered_at = now()
       from due
      where p.id = due.id
     returning p.id, p.seq, p.bill_id, p.kind, p.station, p.esc_base64, p.created_at, p.attempts`,
    [
      resId, outletId,
      cutoffs.kot.toISOString(), cutoffs.bill.toISOString(),
      agentId, leaseUntil.toISOString(), limit,
    ],
  );
  // Same key as the ORDER BY above, because RETURNING does not preserve it.
  return rows.sort((a, b) => {
    const byTime = new Date(a.created_at).getTime() - new Date(b.created_at).getTime();
    return byTime !== 0 ? byTime : Number(a.seq) - Number(b.seq);
  });
}

/**
 * Terminal write, by compare-and-swap. Returns true when THIS call performed the
 * transition, false when the row was already settled (or does not exist).
 *
 * `status in ('pending','delivered')` is the whole idempotency guard. A till that
 * retries an ack it already delivered — which it will, because the ack rides an
 * HTTP call that can fail after the paper came out — must be a no-op, not an
 * error and not a second state change. Widening this to admit the terminal states
 * would let a late duplicate ack overwrite ack_result and re-stamp settled_at,
 * turning "printed at 19:04" into whatever the retry said.
 *
 * A 'failed' ack is TERMINAL too, deliberately. The agent only reports failure
 * after exhausting its own retries against the physical printer; replaying to
 * that printer on every reconnect would loop forever on a jam nobody has cleared.
 * The row stays as the record that it never printed.
 */
export async function AckPrintJob(
  resId: string,
  jobId: string,
  result: "printed" | "failed",
): Promise<boolean> {
  const rows = await runQuery<{ id: string }>(
    `update "PrintJobs"
        set status = case when $3 = 'printed' then 'acked' else 'failed' end,
            settled_at = now(),
            ack_result = $3,
            claimed_until = null
      where id = $1 and res_id = $2
        and status in ('pending','delivered')
      returning id`,
    [jobId, resId, result],
  );
  return rows.length > 0;
}

/**
 * Reaper, half one: flip outstanding jobs that outlived their TTL to 'expired'.
 *
 * Pure hygiene — ClaimPrintJobsForAgent already refuses to replay them — but it
 * turns "this till was offline long enough to lose receipts" into a queryable
 * fact instead of a row that merely stopped matching a predicate.
 *
 * THE LEASE PREDICATE IS REPEATED HERE ON PURPOSE. A job an agent is holding
 * right now must not be expired out from under it: the agent would spool it,
 * report success, and find its ack rejected as already-settled — losing the one
 * record that the receipt actually printed. Waiting out the lease costs a couple
 * of minutes and the next sweep collects it.
 */
export async function ExpirePrintJobs(resId: string, cutoffs: { kot: Date; bill: Date }): Promise<number> {
  const rows = await runQuery<{ id: string }>(
    `update "PrintJobs"
        set status = 'expired', settled_at = now()
      where res_id = $1
        and status in ('pending','delivered')
        and (claimed_until is null or claimed_until < now())
        and created_at <= (case when kind = 'kot' then $2::timestamptz else $3::timestamptz end)
      returning id`,
    [resId, cutoffs.kot.toISOString(), cutoffs.bill.toISOString()],
  );
  return rows.length;
}

/**
 * Reaper, half two: delete settled rows past the retention window.
 *
 * Keyed on settled_at, NEVER on created_at. A job that sat pending for a
 * fortnight because its till was gone is settled ('expired') the instant the
 * reaper first sees it, and a created_at window would delete it in that same
 * sweep — destroying the only record that those receipts were lost, which is the
 * entire point of the 'expired' state. `settled_at is not null` also makes it
 * impossible to purge a live job however old the row is.
 *
 * Bounded by `limit` because DELETE has no LIMIT of its own and the first sweep
 * after this ships could otherwise take one statement across a tenant's entire
 * receipt history.
 */
export async function PurgeSettledPrintJobs(resId: string, olderThan: Date, limit: number): Promise<number> {
  const rows = await runQuery<{ id: string }>(
    `with doomed as (
       select id
         from "PrintJobs"
        where res_id = $1
          and status not in ('pending','delivered')
          and settled_at is not null
          and settled_at < $2::timestamptz
        order by settled_at asc
        limit $3
     )
     delete from "PrintJobs" p
      using doomed d
      where p.id = d.id
     returning p.id`,
    [resId, olderThan.toISOString(), limit],
  );
  return rows.length;
}

/**
 * Does this outlet belong to this restaurant?
 *
 * The replay path's only authorization question. The socket handler derives
 * res_id from the verified session (never from client input), but the outletId a
 * client sends with `joinOutlet` is unverified — and replay READS rows, where
 * joining a room merely subscribes to events nobody sends. RLS keys on res_id
 * alone, so cross-TENANT is already impossible; this closes cross-OUTLET within
 * one tenant, which RLS does not.
 */
export async function OutletBelongsToRestaurant(resId: string, outletId: string): Promise<boolean> {
  const rows = await runQuery<{ id: string }>(
    `select id from "Outlets" where id = $1 and res_id = $2 limit 1`,
    [outletId, resId],
  );
  return rows.length > 0;
}
